def _can_use_numexpr(op, op_str, a, b, dtype_check):
    """ return a boolean if we WILL be using numexpr """
    if op_str is not None:
        # required min elements (otherwise we are adding overhead)
        if np.prod(a.shape) > _MIN_ELEMENTS:
            # check for dtype compatibility
            dtypes = set()
            for o in [a, b]:
                if hasattr(o, "dtypes") and isinstance(o, (pd.DataFrame, pd.Series)):
                    # Use get_dtype_counts if available, replace with value_counts if not
                    if hasattr(o.dtypes, 'value_counts'):
                        s = o.dtypes.value_counts()
                    else:
                        s = o.get_dtype_counts() if hasattr(o, 'get_dtype_counts') else None

                    if s is not None and len(s) > 1:
                        return False
                    dtypes |= set(s.index.astype(str)) if s is not None else set()
                elif isinstance(o, np.ndarray):
                    dtypes |= {o.dtype.name}

            # allowed are a superset
            if not len(dtypes) or _ALLOWED_DTYPES[dtype_check] >= dtypes:
                return True

    return False
